#!/usr/bin/env python3
"""Rebuild the local graphics catalogue using Python's standard library only."""
from pathlib import Path
import hashlib,json,re,struct,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1];ASSETS=ROOT/'assets'
metadata=json.loads((ASSETS/'metadata.json').read_text()) if (ASSETS/'metadata.json').exists() else {}
GROUPS={'brand':'Marka i logo','social':'Social media','marketing':'Materiały promocyjne','screenshots':'Screenshoty produktu','previews':'Podglądy projektu','archive':'Archiwum','author':'Autor'}
TITLES={'01-quick-access':'Quick Access · popup','02-catalogue':'Customization Workspace','03-record-explorer':'Record Explorer','04-compare':'Compare','05-synchronization':'Synchronization','06-favorites':'Favorites','07-script-workflow-inspector':'Script & Workflow Inspector','08-change-plans':'Change Plans','09-navigation-search':'SuiteCraft Search','10-reference-lists':'Reference Lists','11-settings':'Settings','12-list-synchronization':'List Synchronization','13-popup-list-search':'Quick Access · wyszukiwanie list','suitecraft-mark':'Symbol SuiteCraft','suitecraft-mark-on-dark':'Symbol SuiteCraft · na ciemne tło','suitecraft-mark-on-light':'Symbol SuiteCraft · na jasne tło','suitecraft-logo':'Logo SuiteCraft · pełna wersja SVG','icon-16':'Ikona rozszerzenia · 16 px','icon-32':'Ikona rozszerzenia · 32 px','icon-48':'Ikona rozszerzenia · 48 px','icon-128':'Ikona rozszerzenia · 128 px','icon-source':'Ikona · edytowalny SVG'}
def dimensions(p,raw):
 if p.suffix.lower()=='.png':return struct.unpack('>II',raw[16:24])
 if p.suffix.lower()=='.gif':return struct.unpack('<HH',raw[6:10])
 if p.suffix.lower()=='.svg':
  node=ET.fromstring(raw);v=node.attrib.get('viewBox','').replace(',',' ').split()
  if len(v)==4:return tuple(round(float(x),2) for x in v[2:])
  return tuple(float(re.match(r'[\d.]+',node.attrib[k]).group()) for k in ['width','height'])
 if p.suffix.lower() in ['.jpg','.jpeg']:
  i=2
  while i<len(raw):
   if raw[i]!=255:i+=1;continue
   marker=raw[i+1];i+=2
   if marker in [216,217]:continue
   length=int.from_bytes(raw[i:i+2],'big')
   if marker in [192,193,194,195,197,198,199,201,202,203,205,206,207]:return (int.from_bytes(raw[i+5:i+7],'big'),int.from_bytes(raw[i+3:i+5],'big'))
   i+=length
 return None,None
items=[]
for p in ASSETS.rglob('*'):
 if p.suffix.lower() not in {'.png','.svg','.jpg','.jpeg','.gif','.webp','.avif'}:continue
 rel=p.relative_to(ASSETS).as_posix();info=metadata.get(rel,{});raw=p.read_bytes();w,h=dimensions(p,raw);folder=rel.split('/')[0]
 group=folder if folder in GROUPS else 'author' if p.suffix.lower() in ['.jpg','.jpeg'] else 'brand'
 items.append({'path':rel,'title':info.get('title',TITLES.get(p.stem,p.stem.replace('-',' ').replace('_',' '))), 'category':group,'categoryLabel':GROUPS[group], 'status':info.get('status','ready' if group in ['screenshots','social','author'] else 'brand'),'origin':info.get('origin','SuiteCraft Lab · demonstracyjne dane' if group=='screenshots' else 'Zestaw materiałów SuiteCraft'), 'format':p.suffix[1:].upper(),'width':w,'height':h,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'aliases':info.get('aliases',[]),'usage':info.get('usage',[])})
rank={k:i for i,k in enumerate(GROUPS)};items.sort(key=lambda i:(rank[i['category']],i['path']))
catalog={'schemaVersion':1,'categories':[{'id':k,'label':v} for k,v in GROUPS.items()],'items':items}
text=json.dumps(catalog,ensure_ascii=False,indent=2)+'\n';(ASSETS/'catalog.json').write_text(text)
(ASSETS/'gallery-data.js').write_text('// Generated by scripts/build-asset-gallery.py. Works directly with file://.\nwindow.SuiteCraftAssets = '+text.strip()+';\n')
lines=['# SuiteCraft — biblioteka grafik','','Otwórz [galerię grafik](index.html) lokalnie w przeglądarce: miniatury, wyszukiwanie, kategorie, pełny podgląd i pobieranie oryginałów. Galeria działa również bez serwera.','','Istniejące ścieżki używane przez landing page pozostają bez zmian. Identyczne pliki mają jeden oryginał; alternatywne nazwy są zapisane w katalogu. Wersje historyczne i podglądy projektu są oznaczone osobno.','','## Foldery','','| Folder | Zawartość |','| --- | --- |']
for k,v in GROUPS.items():lines.append(f'| `'+('damian-krolikowski.jpg' if k=='author' else k+'/')+f'` | {v} |')
lines+=['','Zdjęcie autora pozostaje w `damian-krolikowski.jpg`, a symbol używany przez stronę w `suitecraft-mark.svg`. Pliki CSS i JS landing page zachowują swoje dotychczasowe ścieżki.','','## Aktualizacja katalogu','','Po dodaniu grafiki do odpowiedniego folderu uruchom z katalogu repozytorium:','','```sh','python3 scripts/build-asset-gallery.py','```','','Opcjonalne nazwy, statusy i pochodzenie edytuj w `assets/metadata.json`. Generator zapisuje `catalog.json`, `gallery-data.js` i ten indeks. Nie wymaga dodatkowych bibliotek.','','## Zawartość','','| Podgląd / oryginał | Format | Wymiary | Status |','| --- | --- | --- |']
for i in items:
 dims=f"{i['width']} × {i['height']}" if i['width'] else '—'
 lines.append(f"| [{i['title']}]({i['path']}) | {i['format']} | {dims} | {i['status']} |")
lines+=['','## Pochodzenie','','Zebrano materiały marki, bannery, publiczne grafiki Store, screenshoty ze sztucznymi danymi oraz podglądy strony. Importowane grafiki zachowują oryginalne bajty. Szczegóły wcześniejszej anonimizacji screenshotów znajdują się w [screenshots/README.md](screenshots/README.md).','','Surowe zrzuty z kont klientów, źródła rozszerzenia, buildy ZIP i prywatne makiety nie należą do tej biblioteki. Przed dodaniem nowych materiałów sprawdź, czy nie zawierają danych klienta. Galeria nie wysyła plików ani wyszukiwań do żadnego serwisu.','']
(ASSETS/'README.md').write_text('\n'.join(lines))
assert len({i['path'] for i in items})==len(items)
print(f'Indexed {len(items)} graphics ({sum(i["bytes"] for i in items)/1024/1024:.2f} MiB).')
